function TierBadge({ tier, size = "md" }) {
  const t = TIERS[tier];
  if (!t) return null;
  const padding = size === "sm" ? "3px 8px" : size === "lg" ? "7px 16px" : "5px 12px";
  const fontSize = size === "sm" ? 10 : size === "lg" ? 13 : 11;
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5,
      padding, borderRadius: 4,
      fontFamily: T.fontMono, fontSize, fontWeight: 500,
      background: `linear-gradient(180deg, ${t.gradTop}, ${t.gradBot})`,
      border: `1px solid ${t.border}`,
      color: t.text,
      letterSpacing: "0.04em",
      whiteSpace: "nowrap",
    }}>
      {t.short}
    </span>
  );
}

function TierDistributionBar({ breakdown }) {
  const total = Object.values(breakdown).reduce((s, n) => s + n, 0);
  if (total === 0) return null;
  const order = ["forum", "spark", "echo", "fog", "heat", "stance", "breach"];
  return (
    <div>
      <div style={{ display: "flex", height: 36, borderRadius: 4, overflow: "hidden", border: `1px solid ${T.borderLight}` }}>
        {order.map(key => {
          const count = breakdown[key] || 0;
          if (count === 0) return null;
          const t = TIERS[key];
          const pct = (count / total) * 100;
          return (
            <div key={key} style={{
              flex: pct,
              background: `linear-gradient(180deg, ${t.gradTop}, ${t.gradBot})`,
              borderRight: `1px solid ${t.border}`,
              display: "flex", alignItems: "center", justifyContent: "center",
              fontFamily: T.fontMono, fontSize: 10, fontWeight: 500, color: t.text,
              minWidth: pct > 4 ? "auto" : 0,
            }}
            title={`${t.name}: ${count} (${pct.toFixed(0)}%)`}>
              {pct > 6 ? count : ""}
            </div>
          );
        })}
      </div>
      <div style={{ display: "flex", marginTop: 8, fontFamily: T.fontMono, fontSize: 9, color: T.textTertiary, letterSpacing: "0.05em", textTransform: "uppercase" }}>
        {order.map(key => {
          const count = breakdown[key] || 0;
          if (count === 0) return null;
          const pct = (count / total) * 100;
          return (
            <div key={key} style={{ flex: pct, textAlign: "center", minWidth: pct > 4 ? "auto" : 0 }}>
              {pct > 6 ? TIERS[key].short : ""}
            </div>
          );
        })}
      </div>
    </div>
  );
}

